import fs from 'node:fs';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const sourcePath = fileURLToPath(import.meta.url);
const source = fs.readFileSync(sourcePath, 'utf8');
const outputPath = sourcePath.replace(/\.mjs$/, '.json');
if (fs.existsSync(outputPath)) throw new Error('Preflight evidence already exists');
const input = String.raw`printf 'A2_ROOT_PREFLIGHT_BEGIN\n'
id
uname -r
printf 'ROOT_PID_NAMESPACE='
readlink /proc/1/ns/pid
printf 'SELF_PID_NAMESPACE='
readlink /proc/self/ns/pid
printf 'PID1_COMM='
cat /proc/1/comm
printf 'BOOT_ID='
cat /proc/sys/kernel/random/boot_id
printf 'UPTIME='
cat /proc/uptime
printf 'TOOLS\n'
command -v python3 python busybox nsenter chroot chronyc chronyd || true
printf 'CHRONYD_PROCESSES\n'
for record in /proc/[0-9]*/comm; do
  IFS= read -r name < "$record" || continue
  case "$name" in
    chronyd)
      base=$(dirname "$record")
      printf 'PROCESS_BEGIN=%s\n' "$base"
      cat "$base/stat"
      sed -n '/^Name:/p;/^State:/p;/^Pid:/p;/^PPid:/p;/^NSpid:/p;/^NStgid:/p;/^Uid:/p' "$base/status"
      printf 'EXE='
      readlink "$base/exe"
      printf 'PID_NAMESPACE='
      readlink "$base/ns/pid"
      printf 'MOUNT_NAMESPACE='
      readlink "$base/ns/mnt"
      printf 'CMDLINE\n'
      tr '\000' '\n' < "$base/cmdline"
      printf 'PROCESS_END\n'
      ;;
  esac
done
printf 'A2_ROOT_PREFLIGHT_END\n'
exit
`;
const decode = buffer => buffer.includes(0) ? buffer.toString('utf16le') : buffer.toString('utf8');
const started = new Date().toISOString();
const result = spawnSync('C:\\Windows\\System32\\wsl.exe', ['--debug-shell'], {
  cwd: 'D:/ClaudeProjects/ai_acknowladge', windowsHide: true,
  input: Buffer.from(input, 'utf8'), timeout: 20000, maxBuffer: 1024 * 1024,
});
const report = {
  recorded_at: started, finished_at: new Date().toISOString(),
  authorization: 'User confirmed the documented administrator preflight, bounded chronyd suspension, tick correction and conditional proxy rerun.',
  scope: 'Read-only WSL root PID namespace preflight; no signals or clock writes.',
  source_file: sourcePath, source_sha256: crypto.createHash('sha256').update(source).digest('hex'), maintenance_source: source,
  command: ['wsl.exe', '--debug-shell'], requested_stdin: input,
  code: result.status, signal: result.signal, error: result.error?.message,
  stdout: decode(result.stdout ?? Buffer.alloc(0)), stderr: decode(result.stderr ?? Buffer.alloc(0)),
};
fs.writeFileSync(outputPath, JSON.stringify(report, null, 2) + '\n', { flag: 'wx' });
process.exitCode = result.status === 0 && report.stdout.includes('A2_ROOT_PREFLIGHT_END') ? 0 : 1;
